// Hand-written `@nestjs/common` stub: only what the extractors read.
//
// It is here rather than hoisted with the other fixtures' packages because this
// fixture is read inside a detached git worktree in a temporary directory,
// where nothing above it resolves. Every decorator has to resolve to a
// declaration in `@nestjs/common` before the adapters believe it, so the module
// specifier is the load-bearing part and the signatures only have to compile.

export interface ModuleMetadata {
  imports?: unknown[];
  controllers?: unknown[];
  providers?: unknown[];
  exports?: unknown[];
}

export declare function Module(metadata: ModuleMetadata): ClassDecorator;
export declare function Injectable(options?: { scope?: unknown }): ClassDecorator;
export declare function Controller(prefix?: string | string[]): ClassDecorator;

export declare function Get(path?: string | string[]): MethodDecorator;
export declare function Post(path?: string | string[]): MethodDecorator;
export declare function Put(path?: string | string[]): MethodDecorator;
export declare function Patch(path?: string | string[]): MethodDecorator;
export declare function Delete(path?: string | string[]): MethodDecorator;

export declare function Body(property?: string): ParameterDecorator;
export declare function Param(property?: string): ParameterDecorator;
export declare function Query(property?: string): ParameterDecorator;
export declare function Inject(token?: unknown): ParameterDecorator;
